import math, pathlib, tempfile, threading
from app import Queue

with tempfile.TemporaryDirectory() as d:
    path = pathlib.Path(d) / 'q.db'
    q1, q2 = Queue(path), Queue(path)
    source = {'nested': [1, {'ok': True}]}
    q1.put('a', source)
    source['nested'][1]['ok'] = False
    first = q2.claim('worker', 0.25, 0.5)
    assert first['payload'] == {'nested': [1, {'ok': True}]}
    first['payload']['nested'].clear()
    assert q1.claim('other', 0.74, 1) is None
    second = q1.claim('worker', 0.75, 1)
    assert second['payload'] == {'nested': [1, {'ok': True}]}
    assert q2.ack(first['receipt'], 0.75) is False
    assert q2.ack(second['receipt'], 0.75) is True
    assert q1.ack(second['receipt'], 0.75) is False
    try:
        q1.put('a', None)
    except ValueError:
        pass
    else:
        raise AssertionError('completed ID was reused')

    for lease in (True, False, 0, -1, math.nan, math.inf, -math.inf):
        q1.put('job-' + str(lease), {'keep': 1})
        before = q1.claim('worker', 2, 1)
        assert before is not None
        # Put an invalid lease attempt against a queue with pending work.
        try:
            q1.claim('worker', 3, lease)
        except ValueError:
            pass
        else:
            raise AssertionError(f'accepted lease {lease"'!r}'"')
        assert q2.ack(before['receipt'], 3) is True

    class Unsupported:
        pass
    for payload in (Unsupported(), float('nan'), [float('inf')]):
        try:
            q1.put('bad-' + str(type(payload)), payload)
        except (TypeError, ValueError, RecursionError):
            pass
        else:
            raise AssertionError('invalid payload accepted')

    q1.put('left', 1)
    q1.put('right', 2)
    barrier = threading.Barrier(2)
    outcomes = []
    def take(queue, name):
        barrier.wait()
        outcomes.append(queue.claim(name, 10, 5))
    threads = [threading.Thread(target=take, args=(q1, 'w1')), threading.Thread(target=take, args=(q2, 'w2'))]
    for thread in threads: thread.start()
    for thread in threads: thread.join()
    assert len([item for item in outcomes if item is not None]) == 2
    assert len({item['receipt']['job_id'] for item in outcomes}) == 2
print('contract checks passed')
PY"

